// Client contracts (part 21.01): the contract is made from the signed-off commercial baseline of the project (10.02) with the terms of the agreement (type, value, dates, payment, retention, advances, price variation, liquidated damages, securities, insurance,
// dispute resolution); it is activated through approval (commercial manager, project director, director) and is then locked: its terms and value change only by an approved amendment or an approved variation (BR-01). The value history is the single source of the
// revised value: original + approved amendments + approved variations (T-01); variations waiting for approval are shown apart. The key clauses carry plain-language summaries and time-bars; obligations have owners, due dates, recurrence and reminders; milestones may be
// linked to payment (lump-sum and milestone billing, 22.03). Money is paise inside and rupees in the API; percentages are basis points inside.
for (const [key, type, def, description, min, max] of [
  ['ctr.contract.require_baseline', 'boolean', true, 'Whether a client contract can be made only for a project whose commercial baseline (10.02) is signed off.', null, null],
  ['ctr.obligation.overdue_escalate_days', 'integer', 3, 'Days an obligation may stay overdue before the commercial manager is told as well as its owner.', 0, 90]]) {
  if (!parameterRegistry.get(key)) parameterRegistry.define({ key, dataType: type, default: def, scopes: ['system', 'company'], description, ...(min == null ? {} : { min, max }) });
}
export const TYPE_LABEL = { ITEM_RATE: 'Item rate', LUMP_SUM: 'Lump sum', EPC: 'EPC', HAM: 'Hybrid annuity (HAM)', COST_PLUS: 'Cost plus', PERCENTAGE_RATE: 'Percentage rate' };
export const STATE_LABEL = { DRAFT: 'Draft', ACTIVE: 'Active', COMPLETED: 'Completed', CLOSED: 'Closed' };
export const CAT_LABEL = { NOTICE: 'Notice', TIME_BAR: 'Time-bar', VARIATION: 'Variation procedure', PAYMENT: 'Payment', TERMINATION: 'Termination', LD: 'Liquidated damages', PVC: 'Price variation', DISPUTE: 'Dispute resolution', INSURANCE: 'Insurance', SECURITY: 'Security', OTHER: 'Other' };
