const addDays = (iso, n) => new Date(Date.parse(`${iso}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10);
const addMonths = (iso, n) => { const d = new Date(Date.parse(`${iso}T00:00:00Z`)); const day = d.getUTCDate(); d.setUTCDate(1); d.setUTCMonth(d.getUTCMonth() + n); const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate(); d.setUTCDate(Math.min(day, last)); return d.toISOString().slice(0, 10); };
/** The next due date of a recurring obligation. */
export const nextDue = (due, rec) => (rec === 'WEEKLY' ? addDays(due, 7) : rec === 'MONTHLY' ? addMonths(due, 1) : rec === 'QUARTERLY' ? addMonths(due, 3) : rec === 'YEARLY' ? addMonths(due, 12) : null);
/** T-01: the revised value is the sum of the approved entries of the value history (original, amendments, variations); pending variations are summed apart. */
export function valueOf(entries) { const ok = entries.filter((e) => e.entry_status === 'APPROVED'); const sum = (k) => ok.filter((e) => e.entry_kind === k).reduce((n, e) => n + e.amount_paise, 0); return { original: sum('ORIGINAL'), amended: sum('AMENDMENT'), varied: sum('VARIATION'), revised: ok.reduce((n, e) => n + e.amount_paise, 0), pending: entries.filter((e) => e.entry_status === 'PENDING' && e.entry_kind === 'VARIATION').reduce((n, e) => n + e.amount_paise, 0) }; }

