      const rows = db.prepare(`SELECT o.*, x.contract_no, x.org_project_id AS pid FROM ctr_obligations o JOIN ctr_contracts x ON x.id = o.contract_id WHERE ${scopeOf(actor, 'ctr.obligation.view')} AND o.deleted_at IS NULL AND x.deleted_at IS NULL AND x.status <> 'CANCELLED' AND ((o.due_date >= :from AND o.due_date <= :to) OR (o.obligation_status = 'OPEN' AND o.due_date < :from))${extra} ORDER BY o.due_date, o.id`).all(P).map((o) => ({ ...oView(o, t), contractNo: o.contract_no, project: pcode(o.pid), projectId: o.pid, clause: o.clause_id ? db.prepare('SELECT clause_no FROM ctr_clauses WHERE id = ?').get(o.clause_id)?.clause_no : null, mine: o.owner_user === actor.user }));
